const config = $('Configuration').first().json;
const doctorByEnum = Object.fromEntries(Object.entries(config.doctorEnums).map(([slug, id]) => [id, slug]));
const items = [];
const seen = new Set();
const push = json => items.push({ json });
const fail = (lead_id, code, details = {}) => push({ outcome: 'failed', lead_id, code, ...details });
const id = value => /^\d+$/.test(String(value)) && Number.isSafeInteger(Number(value)) && Number(value) > 0 ? Number(value) : null;
let expectedPage = 1;
for (const { json: response } of $input.all()) {
  const data = response.body?.data;
  if (response.statusCode !== 200 || !Array.isArray(data?.items) ||
      expectedPage === null || id(data.page) !== expectedPage ||
      (data.nextPage !== null && !(id(data.nextPage) > expectedPage))) {
    return [{ json: { outcome: 'fetch_failed', code: 'invalid_kvik_page', page: expectedPage, http_status: response.statusCode ?? null } }];
  }
  expectedPage = data.nextPage === null ? null : id(data.nextPage);
  for (const lead of data.items) {
    const leadId = id(lead?.id);
    if (!leadId) {
      fail(null, 'invalid_lead_id');
      continue;
    }
    if (seen.has(leadId)) continue;
    seen.add(leadId);
    const created = id(lead.created_at);
    if (!created) {
      fail(leadId, 'invalid_created_at');
      continue;
    }
    if (created < config.dayStart || created > config.runStarted) {
      push({ outcome: 'skipped', code: 'outside_creation_window' });
      continue;
    }
    const fields = Array.isArray(lead.custom_fields_values) ? lead.custom_fields_values : [];
    const value = (fieldId, key) => {
      const entries = fields.filter(field => id(field?.field_id) === fieldId);
      const values = entries[0]?.values;
      return entries.length === 1 && Array.isArray(values) && values.length === 1 ? values[0]?.[key] : null;
    };
    const start = id(value(config.appointmentFieldId, 'value'));
    const date = start && DateTime.fromSeconds(start, { zone: config.timezone });
    if (!date?.isValid) {
      fail(leadId, 'invalid_appointment');
      continue;
    }
    if (start <= config.runStarted || date.toISODate() > config.to) {
      push({ outcome: 'skipped', code: 'outside_appointment_window' });
      continue;
    }
    const doctorEnum = id(value(config.doctorFieldId, 'enum_id'));
    if (!doctorEnum) {
      fail(leadId, 'missing_or_invalid_doctor_enum');
      continue;
    }
    const doctor = doctorByEnum[doctorEnum];
    if (!doctor) {
      push({ outcome: 'skipped', code: 'doctor_not_allowlisted' });
      continue;
    }
    const serviceEnum = id(value(config.serviceFieldId, 'enum_id'));
    const service = catalog[serviceEnum];
    if (!service) {
      fail(leadId, 'unknown_service_enum', { doctor_enum: doctorEnum, service_enum: serviceEnum });
      continue;
    }
    const options = [...new Set(service.slugs.filter(slug => slug.startsWith(doctor + '_')))];
    if (options.length !== 1) {
      fail(leadId, 'no_unique_event_slug', { doctor_enum: doctorEnum, service_enum: serviceEnum });
      continue;
    }
    const nameValue = value(config.patientNameFieldId, 'value');
    const name = typeof nameValue === 'string' ? nameValue.trim() : '';
    const phoneValue = value(config.patientPhoneFieldId, 'value');
    let phone = typeof phoneValue === 'string' ? phoneValue.trim().replace(/[ ().-]/g, '') : '';
    if (/^[78]\d{10}$/.test(phone)) phone = '+7' + phone.slice(1);
    if (!name || name.length > 200 || !/^\+[1-9]\d{6,14}$/.test(phone)) {
      fail(leadId, 'missing_or_invalid_patient_contact', { event_type_slug: options[0] });
      continue;
    }
    push({
      outcome: 'ready',
      lead_id: leadId,
      event_type_slug: options[0],
      start_at: date.toUTC().toISO({ suppressMilliseconds: true }),
      name,
      phone,
      procedure: config.procedureOverrides[serviceEnum] ?? service.name,
    });
  }
}
if (expectedPage !== null) return [{ json: { outcome: 'fetch_failed', code: 'incomplete_kvik_pagination', page: expectedPage } }];
return items.length ? items : [{ json: { outcome: 'empty' } }];

const lead = $('Valid candidate?').itemMatching(0).json;
const config = $('Configuration').first().json;
const response = $input.first().json;
const details = { lead_id: lead.lead_id, event_type_slug: lead.event_type_slug, start_at: lead.start_at };
const fail = code => [{ json: { ...details, outcome: 'failed', code, http_status: response.statusCode ?? null } }];
const questions = response.body?.items;
if (response.statusCode !== 200 || !Array.isArray(questions)) return fail('calnode_questions_unavailable');
const required = questions.filter(question => question.required);
if (required.length !== 1 || !required[0].id || !['text', 'select'].includes(required[0].type)) {
  return fail('unsupported_required_calnode_questions');
}
const procedure = required[0];
if (procedure.type === 'select' && !procedure.options?.includes(lead.procedure)) return fail('procedure_dropdown_mismatch');
if (config.dryRun) return [{ json: { ...details, outcome: 'would_create' } }];
return [{ json: { ...details, outcome: 'submit', booking: {
  event_type_slug: lead.event_type_slug,
  start_at: lead.start_at,
  name: lead.name,
  contact_method: 'phone',
  contact_phone: lead.phone,
  timezone: config.timezone,
  language: 'ru-RU',
  answers: [{ question_id: procedure.id, value: lead.procedure }],
} } }];

const request = $('Write booking?').itemMatching(0).json;
const response = $input.first().json;
const status = response.statusCode ?? null;
const body = response.body;
const confirmed = status === 201 && body?.status === 'confirmed' && typeof body.id === 'string' && body.id;
const details = { lead_id: request.lead_id, event_type_slug: request.event_type_slug, start_at: request.start_at };
if (confirmed) return [{ json: { ...details, outcome: 'confirmed', booking_id: body.id } }];
const code = body?.payment_required ? 'payment_required'
  : status === 409 ? 'slot_unavailable_or_request_in_progress'
  : status === 422 ? 'booking_limit_or_idempotency_conflict'
  : status == null || status >= 500 ? 'booking_outcome_uncertain' : 'calnode_rejected_booking';
return [{ json: { ...details, outcome: 'failed', code, http_status: status } }];

const config = $('Configuration').first().json;
const counts = {};
const skipped = {};
const bookings = [];
const failures = [];
for (const { json: { outcome, code, lead_id, event_type_slug, start_at, booking_id, doctor_enum, service_enum, http_status, page } } of $input.all()) {
  counts[outcome] = (counts[outcome] ?? 0) + 1;
  if (outcome === 'skipped') skipped[code] = (skipped[code] ?? 0) + 1;
  if (outcome === 'confirmed' || outcome === 'would_create') bookings.push({ outcome, lead_id, event_type_slug, start_at, booking_id });
  if (outcome === 'failed' || outcome === 'fetch_failed') failures.push({ lead_id, code, event_type_slug, start_at, doctor_enum, service_enum, http_status, page });
}
return [{ json: { dry_run: config.dryRun, date: config.from, appointment_to: config.to, counts, skipped, bookings, failures } }];
